import java.util.Scanner;
public class PrimalityTest {static boolean prime(int n){if(n<2)return false;for(int i=2;i<=n/i;i++)if(n%i==0)return false;return true;}public static void main(String[] args){Scanner sc=new Scanner(System.in);System.out.print("Enter a (base): ");int a=sc.nextInt();System.out.print("Enter p (number to test): ");int p=sc.nextInt();if(p<2){System.out.println(p+" is composite");return;}if(prime(p)){System.out.println(p+" is prime");return;}long result=modPow(a,p-1,p);if(result==1)System.out.println(p+" is probably prime (Fermat test; not a proof)");else System.out.println(p+" is composite");}static long modPow(long a,long e,long m){long r=1;a=Math.floorMod(a,m);while(e>0){if((e&1)==1)r=(r*a)%m;a=(a*a)%m;e>>=1;}return r;}}
